> +       int ret;
> +
> +       /* v4l2_ext_controls */
> +       ret = scatterlist_builder_add_data(builder, ctrls, sizeof(*ctrls));
> +       if (ret)
> +               return ret;
> +
> +       if (ctrls->count > 0) {
> +               /* array of v4l2_controls */
> +               ret = scatterlist_builder_add_data(builder, ctrls->controls,
> +                                                  sizeof(ctrls->controls[0]) *
> +                                                          ctrls->count);
> +               if (ret)
> +                       return ret;
> +       }
> +
> +       return 0;
> +}
